#!/usr/bin/env python3
"""
Round 124b (culprits-tiles-more), 2 October 2026. Upload after round123b_tiles.py.

- scripts/medical_culprits.py: the company is read from the settlements
  table's own Company column, not the first linked cell (which was often a
  drug: Neurontin, Zoladex, Claritin); cells spanning several rows are
  carried down to the rows under them.

Every file is written whole, and only if it differs.
"""
import base64, pathlib

FILES = {
    'scripts/medical_culprits.py': '',
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"  {name}: already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"  {name}: written")


if __name__ == "__main__":
    main()
